/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var parseJSON = require( '@stdlib/utils/parse-json' );
var isJSON = require( '@stdlib/assert/is-json' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var trim = require( '@stdlib/string/base/trim' );
var Number = require( '@stdlib/number/ctor' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var join = require( '@stdlib/array/base/join' );
var log = require( './../log.js' );
var config = require( './../config.js' );


// VARIABLES //

var URL_PREFIX = config.routes.config;


// FUNCTIONS //

/**
* Returns request options.
*
* @private
* @param {string} body - request body
* @returns {Object} options object
*/
function requestOptions( body ) {
	return {
		'method': 'POST',
		'headers': {
			'Content-Type': 'text/plain'
		},
		'body': body,
		'credentials': 'same-origin'
	};
}


// MAIN //

/**
* Callback invoked upon changing a value in the editor.
*
* @private
* @param {Event} event - event object
*/
function onChange( event ) {
	var self;
	var conf;
	var prop;
	var path;
	var url;
	var tmp;
	var val;
	var obj;
	var ns;
	var i;
	var n;

	self = this;
	conf = this._config;

	// FIXME: other properties/objects

	obj = event.object;
	if ( obj === conf.general ) {
		ns = [ '' ];
	} else if ( obj === conf.padding ) {
		ns = [ 'padding' ];
	} else if ( obj === conf.title ) {
		ns = [ 'title' ];
	} else {
		for ( i = 0; i < conf.axes.length; i++ ) {
			if ( obj === conf.axes[ i ] ) {
				ns = [ 'axes', i.toString() ];
			}
		}
		if ( ns === void 0 ) {
			ns = [ '' ];
		}
	}

	// Resolve the property name by removing any units:
	prop = event.property.split( ' ' )[ 0 ];

	// Convert namespace entries to a path:
	path = join( ns, '/' );

	val = event.value;
	if ( isJSON( val ) ) {
		tmp = parseJSON( val );
		if ( !( tmp instanceof Error ) ) {
			val = tmp;
		}
	} else if ( isString( val ) ) {
		tmp = trim( val );
		if ( prop === 'tickCount' ) {
			n = Number( tmp );
			if ( tmp === '' ) {
				val = void 0;
			} else if ( !isnan( n ) ) {
				val = n;
			} else if ( tmp.indexOf( ',' ) !== -1 ) {
				tmp = tmp.split( /\s*,\s*/ );
				val = {
					'interval': tmp[ 0 ],
					'step': parseInt( tmp[ 1 ], 10 )
				};
			}
		}
	}

	log( 'Editor changed: %s/%s', path, prop );
	this.emit( 'change', {
		'type': 'change',
		'source': 'editor',
		'property': event.property,
		'path': ns.concat( [ prop ] ),
		'value': val
	});

	log( 'Attempting to update configuration...' );
	url = URL_PREFIX+'/'+( ( path ) ? path+'/' : path )+prop;
	fetch( url, requestOptions( event.value.toString() ) ) // eslint-disable-line n/no-unsupported-features/node-builtins
		.then( onResponse )
		.catch( onError );

	/**
	* Callback invoked upon receiving an HTTP response.
	*
	* @private
	* @param {Response} response - response object
	* @returns {void}
	*/
	function onResponse( response ) {
		if ( response.ok ) {
			log( 'Successfully updated configuration.' );
			return;
		}
		console.error( 'Encountered an error when posting change. Status: %d.', response.status );

		// If we failed, we need to roll back to displaying the value from the existing visualization schema:
		self.refresh();
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	*/
	function onError( error ) {
		console.error( 'Encountered an error when posting change. Error: %s.', error.message );

		// If we failed, we need to roll back to displaying the value from the existing visualization schema:
		self.refresh();
	}
}


// EXPORTS //

module.exports = onChange;
